{
  "source": "渡口",
  "lang": "zh",
  "params": {
    "episodes": 6,
    "minutesPerEpisode": 2,
    "genre": "民国情感悬疑",
    "adaptMode": "抽核",
    "preferences": [
      "保留浓雾开船的意象",
      "老周不能改成反派"
    ]
  },
  "adaptation": {
    "core": "浓雾渡口的一船陌生人，各自揣着说不出口的来路，雾散之前每个人都得亮一次底。",
    "keep": [
      {
        "what": "浓雾渡口的封闭空间",
        "why": "天然的单场景悬疑舞台，省景又聚戏",
        "evidence": "雾一厚，连自己的手都看不清。"
      },
      {
        "what": "沈知微怀里的旧皮箱",
        "why": "全剧最强的悬念道具，每集都能给一眼",
        "evidence": "她把一只旧皮箱抱在怀里，指节因为用力而发白。"
      }
    ],
    "cut": [
      {
        "what": "县城当铺的支线",
        "why": "空间跳出渡口，两分钟一集装不下第二个舞台"
      }
    ],
    "merge": [
      {
        "what": "岸边问路的路人甲乙并入胡二爷",
        "why": "同一个功能（打探消息）不需要三张脸"
      }
    ],
    "risks": [
      {
        "what": "全剧困在船上，节奏容易闷",
        "plan": "每集固定一次外部威胁打进来：汽笛、巡查、涨水"
      }
    ],
    "cutNote": "这意味着：全剧困在渡口一夜之内，当铺、县城全部场外处理，终点是开箱翻案，不是进城打官司。",
    "mergeNote": "主角组定的是沈知微与陆行远——全篇只有这两个人有完整的转变弧。"
  },
  "characters": [
    {
      "id": "C01",
      "name": "沈知微",
      "role": "女主",
      "arc": "从抱箱防备到当着全船开箱，把最怕被看见的东西变成翻盘的底牌",
      "from": [
        "原著沈知微"
      ],
      "tier": "lead"
    },
    {
      "id": "C02",
      "name": "陆行远",
      "role": "男主",
      "arc": "大衣口袋里的硬东西从威胁翻成守护，最后一集摊开手心",
      "from": [
        "原著陆行远"
      ],
      "tier": "lead"
    },
    {
      "id": "C03",
      "name": "老周",
      "role": "关键配角",
      "arc": "静止的锚，四十年不问客人来路，最后用一句话掀翻全船的谎",
      "from": [
        "原著老周",
        "合并：岸边艄公的台词功能"
      ],
      "tier": "support"
    },
    {
      "id": "C04",
      "name": "胡二爷",
      "role": "搅局配角",
      "arc": "自来熟的货郎，每集戳一个人的痛处，自己反而是藏得最深的",
      "from": [
        "原著胡二爷",
        "合并：岸边问路的路人甲乙"
      ],
      "tier": "support"
    },
    {
      "id": "C05",
      "name": "岸上挑灯的更夫",
      "tier": "functional",
      "role": "渡口的报时人，雾里只闻梆子声",
      "from": [
        "原创：把原著里「岸上远远的灯火」拟人化成可拍的角色"
      ]
    }
  ],
  "scenes": [
    {
      "id": "S01",
      "name": "渡船船舱",
      "primary": true
    },
    {
      "id": "S02",
      "name": "渡口栈桥",
      "primary": true
    },
    {
      "id": "S03",
      "name": "对岸芦苇滩",
      "primary": false,
      "reusePlan": "栈桥同一机位换背板，芦苇前景遮挡"
    }
  ],
  "props": [
    {
      "id": "P01",
      "name": "旧皮箱",
      "function": "沈知微的底牌与软肋：里面是一摞状纸和一块灵位。从「谁都不许碰」到当众打开，开箱即翻案——全剧最重的一件物证",
      "beatIds": [
        "B01",
        "B04"
      ]
    },
    {
      "id": "P02",
      "name": "县衙旧砚",
      "function": "陆行远的身份物证：砚底刻着县衙的印。掏出即揭破他不是揣枪的人，压到状纸上即与皮箱合成同一桩冤案",
      "beatIds": [
        "B02",
        "B04"
      ]
    }
  ],
  "beats": [
    {
      "id": "B01",
      "type": "悬念钩",
      "weight": "minor",
      "episode": 1,
      "setup": "皮箱谁都不许碰",
      "payoff": "胡二爷伸手要帮忙拎箱，被沈知微一把按住，全船瞬间安静"
    },
    {
      "id": "B02",
      "type": "身份揭破",
      "weight": "major",
      "episode": 3,
      "setup": "陆行远的右手始终揣在大衣口袋里",
      "payoff": "胡二爷一句玩笑逼得他当众掏出口袋——是一方旧砚，不是枪，可砚底刻着县衙的印"
    },
    {
      "id": "B03",
      "type": "反转",
      "weight": "major",
      "episode": 5,
      "setup": "老周四十年不问客人来路",
      "payoff": "老周头一次开口，点破沈知微要去的县城根本没有接应她的人"
    },
    {
      "id": "B04",
      "type": "收束",
      "weight": "minor",
      "episode": 6,
      "setup": "雾开始散",
      "payoff": "皮箱当众打开，船上每个人的谎都落了地，船也到了岸"
    }
  ],
  "episodes": [
    {
      "ep": 1,
      "synopsis": "浓雾清晨，老周照常开船。沈知微抱着旧皮箱最后一个踏上跳板，找了个离所有人最远的位置坐下。胡二爷自来熟地凑过去搭话，顺势伸手要帮她安置箱子，被她死死按住，船舱里的闲谈声戛然而止。",
      "hook": "皮箱里到底装了什么，值得她指节发白",
      "suspense": "陆行远的右手从上船起就没离开过大衣口袋",
      "sceneIds": [
        "S01",
        "S02"
      ],
      "characterIds": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "propIds": [
        "P01"
      ],
      "crowdPlan": "四人同船拆成三个机位区：船头老周单切、舱内沈胡对手戏、船尾陆行远远景",
      "warnings": []
    },
    {
      "ep": 2,
      "synopsis": "船离岸，雾更浓。胡二爷讲起县城集市的见闻探各人口风，说到县衙最近在查一桩旧案，眼睛却始终瞟着沈知微的皮箱。沈知微低头不接话，陆行远却突然接了一句，说那案子查错了人。",
      "hook": "陆行远为什么替一桩旧案说话",
      "suspense": "胡二爷讲见闻时，指名道姓提了沈家",
      "sceneIds": [
        "S01"
      ],
      "characterIds": [
        "C01",
        "C02",
        "C04"
      ],
      "propIds": [
        "P01"
      ],
      "crowdPlan": "三人对话拆成两两正反打，胡二爷居中转场",
      "warnings": [
        "人群"
      ]
    },
    {
      "ep": 3,
      "synopsis": "汽笛声从雾里传来，像是巡查船。胡二爷故意高声打趣，说船上要是有人揣着硬家伙可就说不清了。全船的目光落到陆行远的口袋上。他沉默片刻，当众掏出——一方旧砚，砚底刻着县衙的印。",
      "hook": "县衙的砚台为什么在他身上",
      "suspense": "巡查船的汽笛越来越近，老周却把船往雾更深处撑",
      "sceneIds": [
        "S01"
      ],
      "characterIds": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "propIds": [
        "P02"
      ],
      "crowdPlan": "全员反应戏拆成逐人特写接力，不拍四人同框全景",
      "warnings": []
    },
    {
      "ep": 4,
      "synopsis": "巡查的汽笛擦着船尾远去。陆行远压低声音说明来意：他是替人送还这方砚，物归原主，了一桩冤案的首尾。沈知微听到冤案两个字，抱箱的手臂收得更紧。胡二爷笑着圆场，眼里的算计却淡了下去。",
      "hook": "冤案两个字为什么让她瞬间失态",
      "suspense": "老周在船头咳了一声，像是提醒，又像是警告",
      "sceneIds": [
        "S01"
      ],
      "characterIds": [
        "C01",
        "C02",
        "C04"
      ],
      "propIds": [
        "P01",
        "P02"
      ],
      "crowdPlan": "三人戏收进舱内长凳一条轴线，避免多机位穿帮",
      "warnings": []
    },
    {
      "ep": 5,
      "synopsis": "船过河心，对岸芦苇滩隐约可见。四十年不问客人来路的老周头一次开口，只对沈知微说了一句话：县城北门外早就没有姓沈的接应了。沈知微如遭雷击——她此行投奔的门路，原来是空的。",
      "hook": "老周怎么会知道她要投奔谁",
      "suspense": "胡二爷听到沈姓接应四个字，笑容第一次挂不住",
      "sceneIds": [
        "S01",
        "S03"
      ],
      "characterIds": [
        "C01",
        "C03",
        "C04"
      ],
      "propIds": [],
      "crowdPlan": "老周与沈知微一对一定机位，胡二爷反应用前景虚化带过",
      "warnings": []
    },
    {
      "ep": 6,
      "synopsis": "雾散，岸近。沈知微当着全船打开皮箱：里面是一摞状纸和一块灵位。她不是去投亲，是去翻案。陆行远把旧砚放到状纸上，砚与状纸原属同一桩冤案。胡二爷长叹一声，报出自己在县衙当差的真身份，愿意领他们走侧门。船靠岸，三个人先后踏上跳板，老周撑篙调头，渡口又只剩雾散后的空栈桥。",
      "hook": "状纸和旧砚拼出的到底是谁的冤案",
      "suspense": "胡二爷这个身份是真交底，还是又一层伪装",
      "sceneIds": [
        "S01",
        "S02"
      ],
      "characterIds": [
        "C01",
        "C02",
        "C03",
        "C04",
        "C05"
      ],
      "propIds": [
        "P01",
        "P02"
      ],
      "crowdPlan": "开箱主戏沈知微单人特写扛住，其余三人用过肩与背影分摊",
      "warnings": []
    }
  ]
}

