{
  "source": "签字之前",
  "lang": "zh",
  "params": {
    "episodes": 60,
    "minutesPerEpisode": 1.5,
    "genre": "女频·重生复仇·豪门商战（调香师）",
    "adaptMode": "抽核",
    "preferences": [
      "竖屏短剧，每集 1–2 分钟（按 90 秒设计）",
      "60 集分集大纲需标出付费卡点",
      "第 1–3 集出完整剧本"
    ]
  },
  "adaptation": {
    "core": "被未婚夫和闺蜜联手骗签配方转让、死在火场的调香师沈栀，重生回签婚前协议的那一刻——这一次，她签字之前读完每一个字，从签字台开始，把自己和母亲被偷走的一切讨回来。",
    "keep": [
      {
        "what": "竖屏短剧体量：60 集，单集 1–2 分钟",
        "why": "按 90 秒一集设计，每集只装一个推进加一个钩子，开场三秒内必须有运动中的冲突",
        "evidence": "全剧 60 集，每集 1–2 分钟"
      },
      {
        "what": "付费卡点作为结构骨架",
        "why": "四个卡点（第 10 / 24 / 38 / 48 集）都压在大爆点之后、新悬念之前：观众刚爽完，马上被更大的问题吊住",
        "evidence": "60 集分集大纲，标出付费卡点"
      },
      {
        "what": "签字作为贯穿母题",
        "why": "前世她没读附件就签了，母亲当年签了一张空白页；这一世每个大转折都落在一次签与不签上——撕协议、契约婚、终审、婚书，片名即主题"
      },
      {
        "what": "女主的金手指是调香师的鼻子",
        "why": "嗅觉识破是可视化的爽点（闻香识假、闻出药被换、盲闻对决），比单纯靠前世记忆更有职业质感，也避免主角全知无敌"
      }
    ],
    "cut": [
      {
        "what": "男主同样重生的双重生线",
        "why": "两个人都开挂就没有信息差，男主的价值改为二十年前火灾的亲历者，靠秘密而不是外挂与女主绑定"
      },
      {
        "what": "沈家继母宅斗线",
        "why": "与顾家主线争夺反派资源，90 秒一集装不下两个家庭的内斗；沈父改为单亲、懦弱但爱女"
      },
      {
        "what": "白芷彻底洗白、与女主重修旧好",
        "why": "观众对背叛者的宽恕容忍度低；保留她最后当庭倒戈，但只是赎罪不是和好"
      },
      {
        "what": "海外调香大赛副本",
        "why": "换舞台换人马，场景和角色成本翻倍；职业高光收进发布会盲闻对决一场完成"
      }
    ],
    "merge": [
      {
        "what": "前世的狱友、律师、报信人并入唐楚",
        "why": "女主身边只需要一个懂法的自己人，存证、问询、庭审一张脸扛到底"
      },
      {
        "what": "当年火灾的目击者与沈母的师兄并入陈伯",
        "why": "知情人、职业导师、雪栀配方的见证人是同一个功能，一个人更有分量"
      },
      {
        "what": "顾家的管家、秘书、被收买的护工并入白芷与功能性角色",
        "why": "脏活不必每次换一张脸，内鬼线集中到白芷身上，护工只做一次性的执行者"
      }
    ],
    "risks": [
      {
        "what": "重生复仇题材同质化严重",
        "plan": "差异化落在调香师职业：每个打脸都要有一个闻出来的证据，而不是只靠前世记忆"
      },
      {
        "what": "火场戏三次出现（前世、母亲、终局），AI 生成难度大",
        "plan": "火只拍门缝火光、烟雾与人物逃跑，不拍火焰吞没人体；三次火场共用老厂区一套环境资产，靠时段和年代滤镜区分"
      },
      {
        "what": "婚礼、发布会、庭审的人群戏",
        "plan": "人群一律背景虚化，主戏压在二到三人的正反打；宾客反应用逐人特写接力，不拍满场全景"
      },
      {
        "what": "中段（第 30–45 集）易拖沓",
        "plan": "每三集至少一个爽点，第 38 集卡点前用内鬼线拧紧，第 43–44 集安排舆论低谷制造反弹势能"
      }
    ],
    "cutNote": "这意味着：全剧只有一条复仇主线（夺回配方、揭开两场火的真相）加一条契约婚姻的感情副线，终点是周婉被判、雪栀以沈清禾之名重新发布，沈栀在真正的婚书上读完每一个字再签名。",
    "mergeNote": "主角组定沈栀、陆砚深、顾承泽、周婉四人：沈栀从任人签字到掌握签字权，陆砚深从守秘人到坦白者，顾承泽从加害者到亲手录下母亲认罪，周婉是两场火的源头——这四个人都有完整的弧，白芷只是周婉的棋子，降为重要配角。"
  },
  "characters": [
    {
      "id": "C01",
      "name": "沈栀",
      "role": "女主，25 岁调香师，天生绝对嗅觉，重生者",
      "tier": "lead",
      "arc": "前世轻信、没读附件就签字，被夺走配方死在火场；重生后学会签字之前读完每一个字，从被动防守到主动设局，最后用母亲的日记与自己的鼻子把两场火的真相钉死，并在真正爱她的人递来的协议上放心签名",
      "from": ["原创"]
    },
    {
      "id": "C02",
      "name": "陆砚深",
      "role": "男主，30 岁陆氏集团总裁，顾氏的上游供应商与竞争对手",
      "tier": "lead",
      "arc": "二十年前火灾里被沈清禾推出火场的男孩，十年暗查顾氏却不敢靠近沈栀；从以契约婚姻为名的保护，到为她辞去总裁、在火场替她挡火，最后亲手写下一份可以作废的离婚协议",
      "from": ["原创", "合并：原设定中的神秘投资人"]
    },
    {
      "id": "C03",
      "name": "顾承泽",
      "role": "主反派之一，28 岁顾氏香氛少东家，沈栀的未婚夫",
      "tier": "lead",
      "arc": "靠偷配方撑起继承人光环的伪君子，被假配方反噬、被母亲当成弃子；在知道父亲死于母亲之手后崩溃，最终在火场亲手录下母亲的认罪，用一次真话结束自己作为帮凶的人生",
      "from": ["原创"]
    },
    {
      "id": "C04",
